AssistantMessageToolRequest(name='create', tool_call_id='tooluse_4P2lXKQt4vHd1i0X093J3O', arguments={'file_text': '/* ============================================================
   Design Tokens
   ============================================================ */
:root {
  --bg:          #090909;
  --surface-1:   #111111;
  --surface-2:   #1a1a1a;
  --surface-3:   #242424;
  --surface-4:   #2e2e2e;

  --border:        #272727;
  --border-strong: #383838;

  --accent:        #e8a030;
  --accent-hover:  #f4b840;
  --accent-dim:    rgba(232,160,48,.14);
  --accent-text:   #0a0a0a;

  --red:     #e85050;
  --red-dim: rgba(232,80,80,.15);
  --green:   #45c07a;

  --text-1: #f0f0f0;
  --text-2: #a0a0a0;
  --text-3: #636363;

  --font-sans:    'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-display: 'Georgia', 'Times New Roman', serif;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 14px;
  --radius-xl: 22px;
  --radius-full: 9999px;

  --shadow-sm: 0 2px 8px  rgba(0,0,0,.35);
  --shadow-md: 0 4px 20px rgba(0,0,0,.5);
  --shadow-lg: 0 8px 40px rgba(0,0,0,.7);

  --max-w: 1280px;
  --header-h: 64px;

  --transition: 200ms ease;
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

body {
  background: var(--bg);
  color: var(--text-1);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

ul, ol { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================================
   Accessibility utilities
   ============================================================ */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--accent-text);
  font-weight: 600;
  font-size: .9rem;
  padding: .6rem 1.4rem;
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 0;
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

/* Focus visible — applies globally */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Announcement Bar
   ============================================================ */
.announcement-bar {
  background: var(--accent);
  color: var(--accent-text);
  text-align: center;
  font-size: .85rem;
  font-weight: 500;
  padding: .55rem 1rem;
  letter-spacing: .02em;
}
.announcement-bar a {
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.announcement-bar a:focus-visible {
  outline-color: var(--accent-text);
}

/* ============================================================
   Header
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(9,9,9,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--header-h);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1rem;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
}

.logo {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: .08em;
  color: var(--text-1);
  flex-shrink: 0;
}
.logo span { color: var(--accent); }

/* Primary nav */
.primary-nav {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.primary-nav ul {
  display: flex;
  gap: .25rem;
  align-items: center;
}

.primary-nav a {
  display: block;
  padding: .4rem .75rem;
  font-size: .9rem;
  font-weight: 500;
  color: var(--text-2);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover,
.primary-nav a:focus-visible {
  color: var(--text-1);
  background: var(--surface-2);
}
.primary-nav a[aria-current="page"] {
  color: var(--accent);
}

/* Nav toggle (mobile) */
.nav-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-1);
  transition: background var(--transition);
  margin-left: auto;
}
.nav-toggle:hover { background: var(--surface-2); }

.hamburger {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 20px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition), width var(--transition);
}
.nav-toggle[aria-expanded="true"] .hamburger span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] .hamburger span:nth-child(2) {
  opacity: 0;
  width: 0;
}
.nav-toggle[aria-expanded="true"] .hamburger span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}

.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-1);
  transition: background var(--transition);
}
.icon-btn:hover { background: var(--surface-2); }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-text);
  font-size: .65rem;
  font-weight: 700;
  width: 16px; height: 16px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* ============================================================
   Layout helpers
   ============================================================ */
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 4.5rem 0;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
}

.section-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.15;
}

.section-subtitle {
  font-size: .95rem;
  color: var(--text-2);
  margin-top: .4rem;
}

.link-all {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
  padding-bottom: 1px;
  flex-shrink: 0;
}
.link-all:hover { border-color: var(--accent); }

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  font-family: inherit;
  font-size: .9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  padding: .65rem 1.4rem;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              transform 100ms ease, box-shadow var(--transition);
  border: 1px solid transparent;
}
.btn:active { transform: scale(.98); }

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
}
.btn-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }

.btn-outline {
  background: transparent;
  color: var(--text-1);
  border-color: var(--border-strong);
}
.btn-outline:hover { background: var(--surface-2); border-color: var(--border-strong); }

.btn-ghost {
  background: transparent;
  color: var(--text-2);
  border-color: transparent;
}
.btn-ghost:hover { background: var(--surface-2); color: var(--text-1); }

.btn-sm {
  font-size: .8rem;
  padding: .45rem 1rem;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--surface-1);
  min-height: 560px;
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 80% at 75% 50%, rgba(232,160,48,.10) 0%, transparent 70%),
    radial-gradient(ellipse 50% 50% at 20% 30%, rgba(100,80,200,.12) 0%, transparent 60%);
  pointer-events: none;
  aria-hidden: true;
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: .35;
  pointer-events: none;
}

.hero .container {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  padding-top: 4rem;
  padding-bottom: 4rem;
}

.hero-label {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-dim);
  border: 1px solid rgba(232,160,48,.25);
  border-radius: var(--radius-full);
  padding: .3rem .9rem;
  margin-bottom: 1.25rem;
}
.hero-label .dot {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  animation: pulse 2s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .4; }
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  line-height: 1.08;
  letter-spacing: -.03em;
  font-weight: 700;
  margin-bottom: 1.25rem;
}
.hero-title em {
  font-style: italic;
  color: var(--accent);
}

.hero-description {
  font-size: 1.05rem;
  color: var(--text-2);
  line-height: 1.7;
  max-width: 42ch;
  margin-bottom: 2rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  align-items: center;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}
.hero-stat-value {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -.03em;
  color: var(--text-1);
}
.hero-stat-label {
  font-size: .78rem;
  color: var(--text-2);
  margin-top: .15rem;
}

/* Hero visual */
.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: .75rem;
}
.hero-card {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .75rem;
  transition: transform var(--transition), box-shadow var(--transition);
}
.hero-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.hero-card:first-child {
  grid-column: 1 / -1;
  flex-direction: row;
  justify-content: space-between;
}
.hero-card-emoji { font-size: 2.5rem; line-height: 1; }
.hero-card-title { font-size: .9rem; font-weight: 600; }
.hero-card-price { font-size: .85rem; color: var(--accent); font-weight: 600; }
.hero-card-badge {
  font-size: .7rem;
  font-weight: 700;
  background: var(--red-dim);
  color: var(--red);
  border-radius: var(--radius-full);
  padding: .2rem .6rem;
}

/* ============================================================
   Category Strip
   ============================================================ */
.category-strip {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: var(--surface-1);
  padding: 1.25rem 0;
  overflow: hidden;
}
.category-strip .container {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: .25rem;
}
.category-strip .container::-webkit-scrollbar { display: none; }
.category-chip {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .5rem 1.1rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-strong);
  background: var(--surface-2);
  font-size: .82rem;
  font-weight: 500;
  color: var(--text-2);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}
.category-chip:hover,
.category-chip:focus-visible {
  background: var(--surface-3);
  color: var(--text-1);
  border-color: var(--border-strong);
}
.category-chip.active {
  background: var(--accent-dim);
  color: var(--accent);
  border-color: rgba(232,160,48,.35);
}
.category-chip-icon { font-size: 1rem; }

/* ============================================================
   Product Cards
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.product-card:hover {
  border-color: var(--border-strong);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.product-image {
  position: relative;
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  overflow: hidden;
}

/* Each product has a distinct gradient via data attribute */
.product-image[data-color="purple"]  { background: linear-gradient(135deg, #1a0f40 0%, #2d1b69 100%); }
.product-image[data-color="charcoal"] { background: linear-gradient(135deg, #1a1610 0%, #30281a 100%); }
.product-image[data-color="green"]   { background: linear-gradient(135deg, #0d2010 0%, #1a3d1e 100%); }
.product-image[data-color="brown"]   { background: linear-gradient(135deg, #261510 0%, #3d2214 100%); }
.product-image[data-color="blue"]    { background: linear-gradient(135deg, #0d1a26 0%, #133048 100%); }
.product-image[data-color="warm"]    { background: linear-gradient(135deg, #261a0e 0%, #3d2a10 100%); }

.product-badge {
  position: absolute;
  top: .75rem; left: .75rem;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: var(--radius-full);
}
.badge-sale  { background: var(--red-dim);   color: var(--red);   }
.badge-new   { background: var(--accent-dim); color: var(--accent); }
.badge-best  { background: rgba(69,192,122,.15); color: var(--green); }

.product-wishlist {
  position: absolute;
  top: .75rem; right: .75rem;
  width: 32px; height: 32px;
  background: rgba(0,0,0,.45);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-2);
  transition: background var(--transition), color var(--transition);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] { background: rgba(0,0,0,.7); color: var(--red); }

.product-body {
  padding: 1rem 1.1rem 1.2rem;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: .35rem;
}

.product-category {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-3);
}

.product-name {
  font-size: .975rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--text-1);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .8rem;
}
.stars { color: var(--accent); letter-spacing: 1px; }
.rating-count { color: var(--text-3); font-size: .75rem; }

.product-price {
  display: flex;
  align-items: baseline;
  gap: .6rem;
  margin-top: .15rem;
}
.price-current {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-1);
}
.price-original {
  font-size: .85rem;
  color: var(--text-3);
}
.price-save {
  font-size: .75rem;
  font-weight: 600;
  color: var(--green);
}

.product-footer {
  margin-top: auto;
  padding-top: .75rem;
}

.btn-cart {
  width: 100%;
  background: var(--surface-3);
  color: var(--text-1);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: .6rem;
  font-size: .85rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .45rem;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}
.btn-cart:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}

/* ============================================================
   Deals Section
   ============================================================ */
.deals {
  background: var(--surface-1);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.deals-header {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.deals-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.countdown-block {
  display: flex;
  align-items: center;
  gap: .6rem;
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: .5rem 1rem;
}
.countdown-label {
  font-size: .78rem;
  color: var(--text-2);
  font-weight: 500;
  white-space: nowrap;
}
.countdown-timer {
  display: flex;
  gap: .3rem;
  align-items: center;
}
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.countdown-num {
  font-size: 1.1rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
  min-width: 2ch;
  text-align: center;
}
.countdown-seg {
  font-size: .6rem;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: .06em;
}
.countdown-sep { color: var(--accent); font-weight: 700; font-size: 1rem; padding-bottom: .8rem; }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover {
  border-color: rgba(232,160,48,.35);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.deal-image {
  aspect-ratio: 16 / 9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  position: relative;
}
.deal-image[data-color="teal"]   { background: linear-gradient(135deg, #0d2020, #163535); }
.deal-image[data-color="navy"]   { background: linear-gradient(135deg, #0d1020, #151825); }
.deal-image[data-color="maroon"] { background: linear-gradient(135deg, #200d0d, #381515); }

.deal-discount {
  position: absolute;
  top: .75rem; right: .75rem;
  background: var(--red);
  color: #fff;
  font-size: .8rem;
  font-weight: 700;
  padding: .25rem .6rem;
  border-radius: var(--radius-full);
}

.deal-body { padding: 1.1rem 1.2rem 1.3rem; flex: 1; display: flex; flex-direction: column; gap: .4rem; }
.deal-name { font-size: 1rem; font-weight: 600; }
.deal-price-row { display: flex; align-items: baseline; gap: .6rem; margin-top: .2rem; }
.deal-price-new { font-size: 1.25rem; font-weight: 700; color: var(--text-1); }
.deal-price-old { font-size: .9rem; color: var(--text-3); }

.deal-bar-wrap { margin: .6rem 0; }
.deal-bar-label {
  display: flex;
  justify-content: space-between;
  font-size: .74rem;
  color: var(--text-2);
  margin-bottom: .35rem;
}
.deal-bar {
  height: 5px;
  background: var(--surface-4);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.deal-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-hover));
  border-radius: var(--radius-full);
  transition: width 1s ease;
}

/* ============================================================
   Editorial Section
   ============================================================ */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}
@media (max-width: 900px) {
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .editorial-card:first-child { grid-column: 1 / -1; }
}

.editorial-card {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition);
}
.editorial-card:hover { border-color: var(--border-strong); transform: translateY(-2px); }

.editorial-image {
  aspect-ratio: 16 / 9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  position: relative;
}
.editorial-image[data-color="fashion"]   { background: linear-gradient(135deg, #1a0e22, #2d183d); }
.editorial-image[data-color="tech"]      { background: linear-gradient(135deg, #0e1820, #152838); }
.editorial-image[data-color="lifestyle"] { background: linear-gradient(135deg, #101a10, #1a2e18); }

.editorial-tag {
  position: absolute;
  top: .75rem; left: .75rem;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: .25rem .65rem;
  border-radius: var(--radius-full);
  background: rgba(0,0,0,.55);
  color: var(--text-1);
  border: 1px solid rgba(255,255,255,.12);
}

.editorial-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; gap: .4rem; }
.editorial-meta { font-size: .75rem; color: var(--text-3); }
.editorial-title {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text-1);
}
.editorial-card:first-child .editorial-title { font-size: 1.35rem; }
.editorial-desc { font-size: .875rem; color: var(--text-2); line-height: 1.65; flex: 1; }
.editorial-read {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  font-size: .82rem;
  font-weight: 600;
  color: var(--accent);
  margin-top: .75rem;
  transition: gap var(--transition);
}
.editorial-card a:focus-visible .editorial-read,
.editorial-read:hover { gap: .55rem; }

/* ============================================================
   Newsletter
   ============================================================ */
.newsletter {
  background: var(--surface-1);
  border-top: 1px solid var(--border);
}

.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}

.newsletter-icon { font-size: 2.5rem; margin-bottom: 1rem; }
.newsletter-title {
  font-size: clamp(1.35rem, 2.5vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
  margin-bottom: .6rem;
}
.newsletter-desc { color: var(--text-2); font-size: .95rem; margin-bottom: 1.75rem; }

.newsletter-form { width: 100%; }
.newsletter-row {
  display: flex;
  gap: .5rem;
}

.field-wrap { flex: 1; display: flex; flex-direction: column; gap: .35rem; }
label.newsletter-label {
  font-size: .82rem;
  font-weight: 500;
  color: var(--text-2);
  text-align: left;
}

.input {
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  color: var(--text-1);
  font-family: inherit;
  font-size: .9rem;
  padding: .65rem .9rem;
  width: 100%;
  transition: border-color var(--transition);
}
.input::placeholder { color: var(--text-3); }
.input:focus { outline: none; border-color: var(--accent); }
.input:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.newsletter-help {
  font-size: .76rem;
  color: var(--text-3);
  margin-top: .75rem;
  text-align: center;
}

.newsletter-status {
  margin-top: .75rem;
  font-size: .85rem;
  font-weight: 500;
  min-height: 1.4em;
}
.newsletter-status.success { color: var(--green); }
.newsletter-status.error   { color: var(--red);   }

/* ============================================================
   Toast Notification
   ============================================================ */
.toast-region {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}

.toast {
  background: var(--surface-3);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: .75rem 1.1rem;
  font-size: .875rem;
  font-weight: 500;
  color: var(--text-1);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: .6rem;
  transform: translateX(0);
  opacity: 1;
  transition: opacity var(--transition), transform var(--transition);
  max-width: 300px;
  pointer-events: auto;
}
.toast.hide {
  opacity: 0;
  transform: translateX(1rem);
}
.toast-icon { font-size: 1.1rem; flex-shrink: 0; }

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--surface-1);
  border-top: 1px solid var(--border);
  padding: 3.5rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 2rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
}

.footer-brand-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: .08em;
  color: var(--text-1);
  margin-bottom: .75rem;
  display: inline-block;
}
.footer-brand-logo span { color: var(--accent); }
.footer-tagline { font-size: .875rem; color: var(--text-2); line-height: 1.65; max-width: 28ch; }

.footer-social {
  display: flex;
  gap: .5rem;
  margin-top: 1.25rem;
}
.social-link {
  width: 36px; height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-2);
  font-size: .9rem;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}
.social-link:hover {
  background: var(--surface-3);
  color: var(--text-1);
  border-color: var(--border-strong);
}

.footer-col-title {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-1);
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: .5rem; }
.footer-links a {
  font-size: .875rem;
  color: var(--text-2);
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--text-1); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-copy { font-size: .8rem; color: var(--text-3); }
.footer-legal {
  display: flex;
  gap: 1.25rem;
}
.footer-legal a {
  font-size: .8rem;
  color: var(--text-3);
  transition: color var(--transition);
}
.footer-legal a:hover { color: var(--text-2); }

/* ============================================================
   Divider
   ============================================================ */
.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: 0;
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  :root { --header-h: 56px; }

  .nav-toggle { display: flex; }
  .primary-nav ul {
    display: none;
    position: absolute;
    top: var(--header-h);
    left: 0; right: 0;
    background: var(--surface-1);
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    padding: 1rem;
    gap: .25rem;
  }
  .primary-nav ul.open { display: flex; }
  .primary-nav a { padding: .65rem .85rem; color: var(--text-1); }

  .hero .container { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .hero { min-height: auto; }
  .hero .container { padding-top: 3rem; padding-bottom: 3rem; }

  .editorial-grid { grid-template-columns: 1fr; }

  .footer-grid { grid-template-columns: 1fr 1fr; }

  .newsletter-row { flex-direction: column; }

  .deals-header { gap: .75rem; }
}

@media (max-width: 480px) {
  .section { padding: 3rem 0; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .hero-stats { gap: 1.25rem; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .products-grid .product-image { font-size: 2.5rem; }
  .deals-grid { grid-template-columns: 1fr; }
}

/* ============================================================
   Forced Colors / High Contrast
   ============================================================ */
@media (forced-colors: active) {
  .skip-link { forced-color-adjust: none; }
  .btn-primary { forced-color-adjust: none; }
  .product-badge, .deal-discount { forced-color-adjust: none; }
  .cart-badge { forced-color-adjust: none; }
}
