   Design Tokens
   ============================================================ */
:root {
  --bg:          #090909;
  --surface-1:   #111111;
  --surface-2:   #1a1a1a;
  --surface-3:   #242424;
  --surface-4:   #2e2e2e;

  --border:        #272727;
  --border-strong: #383838;

  --accent:        #e8a030;
  --accent-hover:  #f4b840;
  --accent-dim:    rgba(232,160,48,.14);
  --accent-text:   #0a0a0a;

  --red:     #e85050;
  --red-dim: rgba(232,80,80,.15);
  --green:   #45c07a;

  --text-1: #f0f0f0;
  --text-2: #a0a0a0;
  --text-3: #636363;

  --font-sans:    'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-display: 'Georgia', 'Times New Roman', serif;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 14px;
  --radius-xl: 22px;
  --radius-full: 9999px;

  --shadow-sm: 0 2px 8px  rgba(0,0,0,.35);
  --shadow-md: 0 4px 20px rgba(0,0,0,.5);
  --shadow-lg: 0 8px 40px rgba(0,0,0,.7);

  --max-w: 1280px;
  --header-h: 64px;

  --transition: 200ms ease;
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

body {
  background: var(--bg);
  color: var(--text-1);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

ul, ol { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================================
   Accessibility utilities
   ============================================================ */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--accent-text);
  font-weight: 600;
  font-size: .9rem;
  padding: .6rem 1.4rem;
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 0;
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

/* Focus visible — applies globally */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Announcement Bar
   ============================================================ */
.announcement-bar {
  background: var(--accent);
  color: var(--accent-text);
  text-align: center;
  font-size: .85rem;
  font-weight: 500;
  padding: .55rem 1rem;
  letter-spacing: .02em;
}
.announcement-bar a {
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.announcement-bar a:focus-visible {
  outline-color: var(--accent-text);
}

/* ============================================================
   Header
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(9,9,9,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--header-h);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1rem;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
}

.logo {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: .08em;
  color: var(--text-1);
  flex-shrink: 0;
}
.logo span { color: var(--accent); }

/* Primary nav */
.primary-nav {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.primary-nav ul {
  display: flex;
  gap: .25rem;
  align-items: center;
}

.primary-nav a {
  display: block;
  padding: .4rem .75rem;
  font-size: .9rem;
  font-weight: 500;
  color: var(--text-2);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover,
.primary-nav a:focus-visible {
  color: var(--text-1);
  background: var(--surface-2);
}
.primary-nav a[aria-current="page"] {
  color: var(--accent);
}

/* Nav toggle (mobile) */
.nav-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-1);
  transition: background var(--transition);
  margin-left: auto;
}
.nav-toggle:hover { background: var(--surface-2); }

.hamburger {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 20px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition), width var(--transition);
}
.nav-toggle[aria-expanded="true"] .hamburger span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] .hamburger span:nth-child(2) {
  opacity: 0;
  width: 0;
}
.nav-toggle[aria-expanded="true"] .hamburger span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}

.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-1);
  transition: background var(--transition);
}
.icon-btn:hover { background: var(--surface-2); }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-text);
  font-size: .65rem;
  font-weight: 700;
  width: 16px; height: 16px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* ============================================================
   Layout helpers
   ============================================================ */
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 4.5rem 0;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
}

.section-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.15;
}

.section-subtitle {
  font-size: .95rem;
  color: var(--text-2);
  margin-top: .4rem;
}

.link-all {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
  padding-bottom: 1px;
  flex-shrink: 0;
}
.link-all:hover { border-color: var(--accent); }

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  font-family: inherit;
  font-size: .9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  padding: .65rem 1.4rem;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              transform 100ms ease, box-shadow var(--transition);
  border: 1px solid transparent;
}
.btn:active { transform: scale(.98); }

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
}
.btn-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }

.btn-outline {
  background: transparent;
  color: var(--text-1);
  border-color: var(--border-strong);
}
.btn-outline:hover { background: var(--surface-2); border-color: var(--border-strong); }

.btn-ghost {
  background: transparent;
  color: var(--text-2);
  border-color: transparent;
}
.btn-ghost:hover { background: var(--surface-2); color: var(--text-1); }

.btn-sm {
  font-size: .8rem;
  padding: .45rem 1rem;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--surface-1);
  min-height: 560px;
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 80% at 75% 50%, rgba(232,160,48,.10) 0%, transparent 70%),
    radial-gradient(ellipse 50% 50% at 20% 30%, rgba(100,80,200,.12) 0%, transparent 60%);
  pointer-events: none;
  aria-hidden: true;
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: .35;
  pointer-events: none;
}

.hero .container {
  position: relative;
  z-index: 1;
