        navToggle.setAttribute('aria-expanded', 'false');
        navList.classList.remove('open');
        navToggle.focus();
      }
    });

    // Close nav when a nav link is clicked
    navList.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => {
        navToggle.setAttribute('aria-expanded', 'false');
        navList.classList.remove('open');
      });
    });
  }

