  // Cart state
  // ──────────────────────────────────────────────────────────
  let cartCount = 0;
  const cartBtn   = document.getElementById('cart-btn');
  const cartBadge = document.getElementById('cart-count');

  function updateCart(delta) {
    cartCount = Math.max(0, cartCount + delta);
    const label = cartCount === 0
      ? 'Shopping cart — 0 items'
      : `Shopping cart — ${cartCount} ${cartCount === 1 ? 'item' : 'items'}`;
    cartBtn.setAttribute('aria-label', label);

    if (cartCount > 0) {
      cartBadge.textContent = cartCount > 99 ? '99+' : cartCount;
      cartBadge.removeAttribute('hidden');
    } else {
      cartBadge.setAttribute('hidden', '');
    }
  }

  // ──────────────────────────────────────────────────────────
  // Toast notifications
  // ──────────────────────────────────────────────────────────
  const toastRegion = document.getElementById('toast-region');

  function showToast(message, icon = '✓') {
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.innerHTML = `<span class="toast-icon" aria-hidden="true">${icon}</span>${message}`;
    toastRegion.appendChild(toast);

    // Animate out after 3 s
    setTimeout(() => {
      toast.classList.add('hide');
      toast.addEventListener('transitionend', () => toast.remove(), { once: true });
    }, 3000);
  }

  // ──────────────────────────────────────────────────────────
  // Add to cart buttons (product cards + deal cards)
  // ──────────────────────────────────────────────────────────
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-product]');
    if (!btn) return;

    const name  = btn.dataset.product;
    const price = btn.dataset.price ? `$${btn.dataset.price}` : '';

    updateCart(1);
    showToast(`<strong>${name}</strong> added to cart${price ? ` — ${price}` : ''}`, '🛍️');
  });

  // ──────────────────────────────────────────────────────────
  // Wishlist toggle
  // ──────────────────────────────────────────────────────────
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('.product-wishlist');
    if (!btn) return;

    const isPressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!isPressed));
    btn.textContent = isPressed ? '♡' : '♥';

    // Extract product name from aria-label ("Save X to wishlist")
    const label = btn.getAttribute('aria-label') || '';
    const match = label.match(/^Save (.+?) to wishlist$/);
    const name  = match ? match[1] : 'item';

    if (!isPressed) {
      showToast(`<strong>${name}</strong> saved to wishlist`, '♥');
    }
  });

  // ──────────────────────────────────────────────────────────
  // Category chip selection
  // ──────────────────────────────────────────────────────────
  const chips = document.querySelectorAll('.category-chip');
  chips.forEach((chip) => {
    chip.addEventListener('click', (e) => {
      e.preventDefault();
      chips.forEach((c) => {
        c.classList.remove('active');
        c.removeAttribute('aria-current');
      });
      chip.classList.add('active');
      chip.setAttribute('aria-current', 'true');
    });
  });

  // ──────────────────────────────────────────────────────────
  // Countdown Timer
  // ──────────────────────────────────────────────────────────
  const cdH = document.getElementById('cd-h');
  const cdM = document.getElementById('cd-m');
  const cdS = document.getElementById('cd-s');

  if (cdH && cdM && cdS) {
    // Set a target 5 h 32 m 47 s from now
    const end = Date.now() + ((5 * 3600 + 32 * 60 + 47) * 1000);

    function padTwo(n) {
      return String(n).padStart(2, '0');
    }

    function tick() {
      const remaining = Math.max(0, end - Date.now());
      const totalSec  = Math.floor(remaining / 1000);
      const h = Math.floor(totalSec / 3600);
      const m = Math.floor((totalSec % 3600) / 60);
      const s = totalSec % 60;

      cdH.textContent = padTwo(h);
      cdM.textContent = padTwo(m);
      cdS.textContent = padTwo(s);

      // Update accessible labels
      cdH.setAttribute('aria-label', `${h} hours`);
      cdM.setAttribute('aria-label', `${m} minutes`);
      cdS.setAttribute('aria-label', `${s} seconds`);

      if (remaining > 0) {
        setTimeout(tick, 1000);
      } else {
        cdH.closest('.countdown-block').innerHTML =
          '<p class="countdown-label">Sale ended</p>';
      }
    }

    tick();
  }

  // ──────────────────────────────────────────────────────────
  // Newsletter form
  // ──────────────────────────────────────────────────────────
  const newsletterForm   = document.getElementById('newsletter-form');
  const newsletterStatus = document.getElementById('newsletter-status');
  const newsletterEmail  = document.getElementById('newsletter-email');

  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const email = (newsletterEmail.value || '').trim();

      if (!email) {
        newsletterStatus.textContent = 'Please enter your email address.';
        newsletterStatus.className = 'newsletter-status error';
        newsletterEmail.focus();
        return;
      }

      // Basic format check
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        newsletterStatus.textContent = 'Please enter a valid email address.';
        newsletterStatus.className = 'newsletter-status error';
        newsletterEmail.focus();
        return;
      }

      // Simulate success
      newsletterStatus.textContent = '🎉 You\'re subscribed! Check your inbox for a welcome offer.';
      newsletterStatus.className = 'newsletter-status success';
      newsletterForm.reset();
    });
  }

  // ──────────────────────────────────────────────────────────
  // Sticky header: add 'scrolled' class for styling hints
  // ──────────────────────────────────────────────────────────
  const header = document.querySelector('.site-header');
  if (header) {
    const onScroll = () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

})();
