  mainTabIndex:/<main[^>]+tabindex=\"-1\"/.test(html),
  h1Count:     (html.match(/<h1[\s>]/g)||[]).length,
  h2Tags:      (html.match(/<h2[\s>]/g)||[]).length,
  h3Tags:      (html.match(/<h3[\s>]/g)||[]).length,
