  reducedMotion: fs.readFileSync('styles.css','utf8').includes('prefers-reduced-motion'),
  forcedColors:  fs.readFileSync('styles.css','utf8').includes('forced-colors'),
};
Object.entries(checks).forEach(([k,v]) => console.log((v ? '✓' : '✗') + ' ' + k + ': ' + JSON.stringify(v)));
"

