.newsletter-help {
  font-size: .76rem;
  color: var(--text-3);
  margin-top: .75rem;
  text-align: center;
}

.newsletter-status {
  margin-top: .75rem;
  font-size: .85rem;
  font-weight: 500;
  min-height: 1.4em;
