  font-weight: 500;
  color: var(--text-2);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover,
.primary-nav a:focus-visible {
  color: var(--text-1);
  background: var(--surface-2);
