.social-link:hover {
  background: var(--surface-3);
  color: var(--text-1);
  border-color: var(--border-strong);
}

.footer-col-title {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-1);
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: .5rem; }
