.deals-header {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.deals-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.countdown-block {
  display: flex;
  align-items: center;
  gap: .6rem;
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: .5rem 1rem;
}
.countdown-label {
  font-size: .78rem;
  color: var(--text-2);
  font-weight: 500;
  white-space: nowrap;
}
.countdown-timer {
